1032	fn complete_arg_value(
1033	    value: Result<&str, &OsStr>,
1034	    arg: &clap::Arg,
1035	    current_dir: Option<&std::path::Path>,
1036	    arg_index: usize,
1037	) -> Vec<CompletionCandidate> {
1038	    let mut values = Vec::new();
1039	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
1040	
1041	    let (prefix, value) =
1042	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
1043	
1044	    let value_os = match value {
1045	        Ok(value) => OsStr::new(value),
1046	        Err(value_os) => value_os,
1047	    };
1048	
1049	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
1050	        values.extend(completer.complete_at(arg_index, value_os));
1051	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
1052	        values.extend(complete_value_candidates(
1053	            value_os,
1054	            completer.value_candidates(),
1055	        ));
1056	    } else if let Some(possible_values) = possible_values(arg) {
1057	        if let Ok(value) = value {
1058	            values.extend(complete_candidates_str(
1059	                value,
1060	                possible_value_candidates(possible_values),
1061	            ));
1062	        }
1063	    } else {
1064	        match arg.get_value_hint() {
1065	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
1066	                // Should not complete
1067	            }
1068	            clap::ValueHint::AnyPath => {
1069	                values.extend(complete_path(value_os, current_dir, &|_| true));
1070	            }
1071	            clap::ValueHint::FilePath => {
1072	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
1073	            }
1074	            clap::ValueHint::DirPath => {
1075	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
1076	            }
1077	            clap::ValueHint::ExecutablePath => {
1078	                use is_executable::IsExecutable;
1079	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
1080	            }
1081	            clap::ValueHint::CommandName
1082	            | clap::ValueHint::CommandString
1083	            | clap::ValueHint::CommandWithArguments
1084	            | clap::ValueHint::Username
1085	            | clap::ValueHint::Hostname
1086	            | clap::ValueHint::Url
1087	            | clap::ValueHint::EmailAddress => {
1088	                // No completion implementation
1089	            }
1090	            _ => {
1091	                // Safe-ish fallback
1092	                values.extend(complete_path(value_os, current_dir, &|_| true));
1093	            }
1094	        }
1095	
1096	        values.sort();
1097	    }
1098	
1099	    if let Some(prefix) = prefix {
1100	        values = values
1101	            .into_iter()
1102	            .map(|comp| comp.add_prefix(prefix))
1103	            .collect();
1104	    }
1105	    values = values
1106	        .into_iter()
1107	        .map(|comp| {
1108	            if comp.get_tag().is_some() {
1109	                comp
1110	            } else {
1111	                comp.tag(Some(arg.to_string().into()))
1112	            }
1113	        })
1114	        .collect();
1115	
1116	    debug!("complete_arg_value: values={values:?}");
1117	    values
1118	}
