1187	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
1188	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
1189	fn longs_and_visible_aliases(
1190	    p: &clap::Command,
1191	    disabled: &HashSet<Id>,
1192	) -> Vec<CompletionCandidate> {
1193	    debug!("longs: name={}", p.get_name());
1194	
